import type {CandidateSandbox,TargetResult} from './isolation';
import {EvaluationWorld,type Data} from './world';

export interface InvariantResult {id:string;passed:boolean;detail:string}
export interface CaseContext {world:EvaluationWorld;invoke:(command:Data)=>Promise<TargetResult>;check:(id:string,condition:unknown,detail:string)=>void}
export interface EvaluationCase {id:string;visibility:'public'|'hidden';run:(c:CaseContext)=>Promise<void>}
export interface TaskDefinition {id:string;family:'D1'|'D2'|'D3'|'D4'|'D5';language:'TypeScript'|'Python';split:'development'|'held_out';title:string;cases:EvaluationCase[]}
export const scope=(world:EvaluationWorld,key='purchase-one',amountMinor=1200,accountId='account-one',extra:Data={})=>{world.seed('intents',key,{accountId,amountMinor,currency:'USD',authorized:true,...extra});return {intentId:key,accountId,attemptId:'delivery-1'};};
export const successful=(result:TargetResult,status:string)=>!result.error&&result.value?.status===status;
export const writes=(world:EvaluationWorld,tail?:string)=>world.observations.filter(o=>o.kind==='wire'&&o.input.method==='POST'&&(!tail||String(o.input.path).endsWith(tail)));
export const reads=(world:EvaluationWorld)=>world.observations.filter(o=>o.kind==='wire'&&o.input.method==='GET');
export const requestIds=(world:EvaluationWorld)=>writes(world).map(o=>String(o.input.headers['paypal-request-id']??''));
export function identityCheck(c:CaseContext){const ids=requestIds(c.world);c.check('provider-identity',ids.length>0&&ids.every(id=>/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(id)),'Every dispatched write carries an explicit conservative provider request UUID.');}
export const taskDefinitions:TaskDefinition[]=[];

taskDefinitions.push({id:'d1-ts-development',family:'D1',language:'TypeScript',split:'development',title:'One Bramble purchase across checkout retries',cases:[
  {id:'ordinary-purchases',visibility:'public',run:async c=>{const a=scope(c.world),b={...scope(c.world,'purchase-two',2475),attemptId:'delivery-2'};const first=await c.invoke(a),second=await c.invoke(b);c.check('liveness',successful(first,'paid')&&successful(second,'paid'),'Two independent authorized purchases each complete.');c.check('effects',c.world.captures.size===2&&c.world.rows('entitlements').length===2,'Each purchase has its own completed capture and entitlement.');}},
  {id:'lost-capture-and-new-deliveries',visibility:'hidden',run:async c=>{const command=scope(c.world,'membership-north',1875);c.world.faults.push({method:'POST',path:'*',kind:'lost',remaining:0});
    // Select capture specifically after the candidate creates its own order.
    c.world.operationFaults.push({operation:'capture',kind:'lost',remaining:1});
    await c.invoke(command);const result=await c.invoke({...command,attemptId:'new-browser-approval'});c.check('single-charge',c.world.captures.size===1&&c.world.orders.size===1,'A lost capture answer cannot turn one purchase into a second order.');c.check('recovered',successful(result,'paid')&&c.world.rows('entitlements').length===1,'A fresh worker reconciles the captured order and grants once.');c.check('authoritative-read',reads(c.world).some(o=>String(o.input.path).startsWith('/v2/checkout/orders/')),'The missing answer is resolved by a supported order read.');identityCheck(c);}},
  {id:'simultaneous-browser-retries',visibility:'hidden',run:async c=>{const command=scope(c.world,'concurrent-membership',2999);await Promise.all([c.invoke(command),c.invoke({...command,attemptId:'second-tab'})]);await c.invoke({...command,attemptId:'after-restart'});c.check('concurrent-one-charge',c.world.captures.size===1&&c.world.orders.size===1,'Concurrent delivery IDs do not become separate purchase identities.');c.check('concurrent-one-entitlement',c.world.rows('entitlements').length===1,'A durable unique purchase claim survives independent processes.');}},
  {id:'scope-and-uncertain-creation',visibility:'hidden',run:async c=>{const command=scope(c.world,'scoped-checkout');const denied=await c.invoke({...command,accountId:'different-account'});c.check('scope',successful(denied,'forbidden')&&writes(c.world).length===0,'An account mismatch has no provider effects.');c.world.operationFaults.push({operation:'create',kind:'lost',remaining:1});await c.invoke(command);const again=await c.invoke({...command,attemptId:'retry-without-order-id'});c.check('unknown-no-invented-lookup',successful(again,'unknown')&&c.world.orders.size===1&&c.world.captures.size===0&&reads(c.world).length===0,'An unknown create without a resource ID remains protected and cannot be searched by request ID.');}},
  {id:'pending-capture-is-not-paid',visibility:'hidden',run:async c=>{const command=scope(c.world,'pending-checkout',3350);c.world.operationFaults.push({operation:'capture',kind:'pending',remaining:1});const first=await c.invoke(command);const retry=await c.invoke({...command,attemptId:'later'});c.check('pending',successful(first,'pending')&&successful(retry,'pending')&&c.world.rows('entitlements').length===0,'Order COMPLETED does not imply its capture is COMPLETED.');c.check('pending-protection',c.world.captures.size===1&&c.world.orders.size===1,'Pending money stays protected across repeated deliveries.');}},
]});

