export function definition(id:string){const task=taskDefinitions.find(t=>t.id===id);if(!task)throw new Error(`Unknown evaluation task ${id}`);return task;}
export async function runCase(test:EvaluationCase,world:EvaluationWorld,sandbox:CandidateSandbox){const checks:InvariantResult[]=[];await test.run({world,invoke:async command=>{const result=await sandbox.invoke(world,command);world.record('trusted-grader','invocation-result',{command},result);return result;},check:(id,condition,detail)=>checks.push({id:`${test.id}/${id}`,passed:condition===true,detail})});return checks;}
